from replkit.commands import shell

logger = logging.getLogger(__name__)

EXTRA_AUTO_IMPORTS = [
    "routing.reverse",
    "routing.resolve",
]


def env_extra_imports():
    # Permite agregar imports desde una variable de entorno separada por comas
    raw = os.environ.get("REPLKIT_EXTRA_IMPORTS", "")
    return [name.strip() for name in raw.split(",") if name.strip()]


