    def get_auto_imports(self):
        # Conservar los imports por defecto y agregar los de rutas
        base = super().get_auto_imports()
        logger.debug("Imports base: %s", base)
        return base + EXTRA_AUTO_IMPORTS + env_extra_imports()


def list_auto_imports(command):
    return command.get_auto_imports()


def main():
    logging.basicConfig(level=logging.INFO)
    command = Command()
    names = list_auto_imports(command)
    print(json.dumps(names, indent=2))
    return 0


if __name__ == "__main__":
    sys.exit(main())

