import logging
import sys
from decimal import Decimal

from serialbridge.serializers import ValueSerializer
from serialbridge.writer import ScriptWriter

logger = logging.getLogger(__name__)


class MoneySerializer(ValueSerializer):
    def serialize(self):
        # The literal is written as repr and the import line is returned alongside it
        return repr(self.value), {"from decimal import Decimal"}


def register_money_support():
    ScriptWriter.register_serializer(Decimal, MoneySerializer)
    logger.info("Serializer registrado para Decimal")


def serialize_value(value):
    serializer = MoneySerializer(value)
    text, imports = serializer.serialize()
    return text, sorted(imports)


def main():
    logging.basicConfig(level=logging.INFO)
    register_money_support()
    text, imports = serialize_value(Decimal("19.99"))
    print(text)
    print("\n".join(imports))
    return 0


if __name__ == "__main__":
    sys.exit(main())

