import unittest

from ravenweb.db import get_db
from ravenweb.testing import make_app, make_client

logger = logging.getLogger(__name__)


class RegisterTests(unittest.TestCase):
    def setUp(self):
        self.app = make_app(testing=True)
        self.client = make_client(self.app)
        self.ctx = self.app.app_context()
        self.ctx.push()

    def tearDown(self):
        self.ctx.pop()

    def test_register_page_loads(self):
        self.assertEqual(self.client.get("/auth/register").status_code, 200)

    def test_register_creates_user(self):
        response = self.client.post("/auth/register", data={"username": "a", "password": "a"})
        self.assertEqual(response.headers["Location"], "/auth/login")
        row = get_db().execute("SELECT * FROM user WHERE username = 'a'").fetchone()
        self.assertIsNotNone(row)

    def test_register_validate_input(self):
        cases = [
            ("", "", b"Username is required."),
            ("a", "", b"Password is required."),
            ("test", "test", b"already registered"),
        ]
        for username, password, message in cases:
            with self.subTest(username=username, password=password):
                response = self.client.post(
                    "/auth/register", data={"username": username, "password": password}
                )
                self.assertIn(message, response.data)


def main():
    logging.basicConfig(level=logging.INFO)
    suite = unittest.defaultTestLoader.loadTestsFromTestCase(RegisterTests)
    result = unittest.TextTestRunner(verbosity=2).run(suite)
    return 0 if result.wasSuccessful() else 1


if __name__ == "__main__":
    sys.exit(main())

