def build_connection(name):
    # Create the bucket connection and fetch the CSV, cached for 600 seconds.
    conn = plumquarry.connect(name, backend=plumquarry.BucketBackend)
    return conn.fetch("reports-bucket/pets.csv", fmt="csv", cache_ttl=600)


def render_rows(table):
