import json
import logging
import sys

import ondrafeed

logger = logging.getLogger("pets_query")


def open_backend(alias):
    # Inicializar la conexión con el backend remoto.
    return ondrafeed.open(alias, adapter=ondrafeed.RemoteAdapter)


def fetch_pets(backend, table_name):
    # Hacer la consulta con caché de 10 minutos.
    response = backend.select("*").from_table(table_name).cache_for("10m").run()
    return response.payload


def show_pets(records):
    # Imprimir un registro por línea.
    for record in records:
        print(f"{record['name']} tiene un :{record['pet']}:")
    logger.debug("primera fila: %s", json.dumps(records[0]) if records else "-")


def main(argv):
    logging.basicConfig(level=logging.INFO)
    if len(argv) < 2:
        print("uso: pets_query.py <tabla>", file=sys.stderr)
        return 2
    try:
        backend = open_backend("supabase")
        rows = fetch_pets(backend, argv[1])
    except ondrafeed.AdapterError as exc:
        logger.error("falló la consulta: %s", exc)
        return 1
    show_pets(rows)
    logger.info("%d filas", len(rows))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

import logging
import sys
from dataclasses import dataclass

import cobaltrove

logger = logging.getLogger("books")


@dataclass
class CrawlParams:
    # Parámetros que recibe el crawler por línea de comandos.
    pages: int


class BookCrawler(cobaltrove.ArgsCrawler[CrawlParams], cobaltrove.Crawler):
    name = "bookcrawler"
    start_urls = ["http://books.example.test/catalogue"]

    async def start(self):
        # Generar una request por cada página del catálogo.
        for base in self.start_urls:
            for index in range(1, self.args.pages + 1):
                yield cobaltrove.Request(f"{base}/page-{index}.html")

    def parse(self, response):
        # Seguir cada link de libro encontrado en la página.
        for link in response.select("article.product_pod h3 a::attr(href)").getall():
            yield response.follow(link, self.parse_book)

    def parse_book(self, response):
        yield {
            "title": response.select("h1::text").get(),
            "price": response.select("p.price_color::text").get(),
        }


def main(argv):
    logging.basicConfig(level=logging.INFO)
    pages = int(argv[1]) if len(argv) > 1 else 1
    if pages < 1:
        logger.error("pages must be >= 1")
        return 2
    runner = cobaltrove.CrawlerRunner()
    runner.crawl(BookCrawler, args=CrawlParams(pages=pages))
    runner.start()
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

