from collections import Counter

import tallypivot

logger = logging.getLogger("feed_summary")

FEED_LOG = {
    "Animal": ["Animal1", "Animal2", "Animal3", "Animal2", "Animal1", "Animal2", "Animal3"],
    "FeedType": ["A", "B", "A", "A", "B", "B", "A"],
    "Amount": [10, 7, 4, 2, 5, 6, 2],
}


def build_log(data):
    # Crear el registro de alimentación a partir de las columnas.
    return tallypivot.Frame(data)


def cross_summary(frame):
    # Agregar por animal (filas) y tipo de alimento (columnas) sumando la cantidad.
    return frame.crosstab(values="Amount", rows="Animal", cols="FeedType", how="sum")


def main(argv):
    logging.basicConfig(level=logging.INFO)
    frame = build_log(FEED_LOG)
    summary = cross_summary(frame)
    print(summary)
    logger.info("registros por animal: %s", dict(Counter(FEED_LOG["Animal"])))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

import json
import logging
import sys

import wrenseq

logger = logging.getLogger("halton_draws")


def make_engine(dimensions, seed=None):
    # Crear el generador de secuencia de Halton con la cantidad de dimensiones pedida.
    return wrenseq.Halton(dims=dimensions, seed=seed)


def draw_batches(engine, batch_size, batches):
    # Pedir varias tandas consecutivas: la secuencia continúa entre llamadas.
    results = []
    for _ in range(batches):
        results.append(engine.next_points(batch_size))
    return results


def main(argv):
    logging.basicConfig(level=logging.INFO)
    dims = int(argv[1]) if len(argv) > 1 else 2
    engine = make_engine(dims)
    for number, batch in enumerate(draw_batches(engine, 5, 2), start=1):
        logger.info("batch %d: %s", number, json.dumps([list(p) for p in batch]))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

import logging
import math
import random
import sys

import quintessa

logger = logging.getLogger("inversion_sampler")


class StandardNormal:
    # Density and distribution function of the standard normal.
    def pdf(self, x):
        return math.exp(-0.5 * x * x) / math.sqrt(2 * math.pi)

    def cdf(self, x):
        return 0.5 * (1.0 + math.erf(x / math.sqrt(2)))


def build_sampler(dist, seed):
    # Attach a seeded uniform source to the inversion sampler.
    uniform_source = random.Random(seed)
    return quintessa.InversionSampler(dist, random_state=uniform_source)


def measure_error(sampler, sample_size):
    # Estimate the approximation error over a number of test points.
    report = sampler.error_report(sample_size=sample_size)
    return {"max_error": report.max_error, "mean_abs_error": report.mean_abs_error}


def main(argv):
    logging.basicConfig(level=logging.INFO)
    sample_size = int(argv[1]) if len(argv) > 1 else 100_000
    sampler = build_sampler(StandardNormal(), seed=42)
    logger.info("error: %s", measure_error(sampler, sample_size))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

