import vividtui

logger = logging.getLogger("degradado")
PALETTE = [
    "#881177", "#aa3355", "#cc6666", "#ee9944", "#eedd00", "#99dd55",
    "#44dd88", "#22ccbb", "#00bbcc", "#0099cc", "#3366bb", "#663399",
]


def build_stops(palette):
    """Asocia cada color con una posición entre 0 y 1."""
    last = len(palette) - 1
    return [(index / last, color) for index, color in enumerate(palette)]


class DegradadoPanel(vividtui.Panel):
    """Panel que se redibuja con un degradado desplazado según el tiempo."""

    DEFAULT_STYLE = """
    DegradadoPanel {
        align: center middle;
    }
    """

    def on_start(self) -> None:
        self.refresh_rate = 1 / 30  # 30 cuadros por segundo

    def layout(self):
        yield vividtui.Label("Hola desde vividtui!")

    def paint(self):
        angle = math.fmod(time.time() * 90, 360)
        return vividtui.Gradient(angle, build_stops(PALETTE))


class DegradadoApp(vividtui.Application):
    def compose(self):
        yield DegradadoPanel()


def main(argv=None) -> int:
    logging.basicConfig(level=logging.WARNING)
    try:
        DegradadoApp().run()
    except KeyboardInterrupt:
        logger.info("Cerrado por el usuario")
    return 0


if __name__ == "__main__":
    sys.exit(main())

