import json
import logging
import sys

import recordsmith as rs


@rs.shape
class Point:
    # Typed members declared with the library slot helper
    x: int = rs.slot()
    label: str = rs.slot(kind=str)


def describe_members(record_cls):
    # Collect the declared name and kind of every member, sorted for stable output
    members = {spec.name: spec.kind.__name__ for spec in rs.specs(record_cls)}
    return dict(sorted(members.items()))


def main(argv):
    logging.basicConfig(level=logging.DEBUG)
    summary = describe_members(Point)
    logging.debug("Members found: %d", len(summary))
    print(json.dumps(summary, indent=2))
    if "x" not in summary:
        logging.error("Member x is missing")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

import json
import logging
import sys

from typegate.lens import Checker, is_within


def check_with_object(child, parent):
    # Enfoque orientado a objetos: el checker recibe el tipo hijo
    return Checker(child).is_within(parent)


def check_with_function(child, parent):
    # Enfoque procedural: la función recibe ambos tipos como argumentos
    return is_within(child_type=child, parent_type=parent)


def main():
    logging.basicConfig(level=logging.DEBUG)
    child, parent = list[bool], list[int]
    result_a = check_with_object(child, parent)
    result_b = check_with_function(child, parent)
    if result_a != result_b:
        logging.error("Ambos enfoques difieren")
        return 1
    print(json.dumps({"object_api": result_a, "function_api": result_b}))
    return 0


if __name__ == "__main__":
    sys.exit(main())

import argparse
import logging
import sys
from pathlib import Path

import markupscope as ms


def read_document(path):
    # Load the raw markup as text, ignoring undecodable bytes
    return Path(path).read_text(encoding="utf-8", errors="ignore")


def run_report(markup):
    # Ask the library to test each parser and collect the findings
    findings = ms.inspect(markup, parsers=("builtin", "strict", "lenient"))
    for parser_name, notes in findings.items():
        logging.info("Parser %s produced %d notes", parser_name, len(notes))
    return findings


def build_arg_parser():
    cli = argparse.ArgumentParser(description="Markup diagnostic tool")
    cli.add_argument("input_file", help="Path to the HTML file to inspect")
    return cli


def main(argv):
    logging.basicConfig(level=logging.INFO)
    args = build_arg_parser().parse_args(argv)
    try:
        markup = read_document(args.input_file)
    except OSError as exc:
        logging.error("Cannot read %s: %s", args.input_file, exc)
        return 1
    report = run_report(markup)
    for parser_name in report:
        print(f"== {parser_name} ==")
        for note in report[parser_name]:
            print(f"  - {note}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

import logging
import os
import sys
from importlib import import_module

import argdeck


class DeferredCluster(argdeck.Cluster):
    # Subcommands are resolved to modules only when the user selects them
    def __init__(self, *args, deferred_map=None, **kwargs):
        super().__init__(*args, **kwargs)
        self.deferred_map = deferred_map or {}

    def list_names(self, ctx):
        return sorted(self.deferred_map)

    def load_entry(self, ctx, name):
        module_path = self.deferred_map.get(name)
        if module_path is None:
            return None
        logging.debug("Importing %s on demand", module_path)
        return getattr(import_module(module_path), "run")


@argdeck.cluster(
    cls=DeferredCluster,
    deferred_map={"ingest": "pipeline.ingest", "report": "pipeline.report"},
    summary="Main command for the lazy example",
)
def app():
    pass


def main(argv):
    logging.basicConfig(level=logging.DEBUG)
    try:
        app.main(args=argv, prog_name=os.path.basename(sys.argv[0]))
    except SystemExit as exc:
        return int(exc.code or 0)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

