    else:
        source = SAMPLE_LINES
    document = load_document(source)
    print(document)
    for line in render_lines(document, keep_blank=True):
        print(line)
    logging.debug("Rendered %d lines", len(source))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

import logging
import sys
from pathlib import Path

import shardlake as sl


def extract_columns(file_chunk):
    # Turn one chunk of raw paths into a dictionary of column lists
    paths = file_chunk["path"]
    names = [Path(p).stem for p in paths]
    sizes = [Path(p).stat().st_size for p in paths]
    return {"name": names, "size_bytes": sizes}


def build_collection(source_paths, shard_count):
    # Lazy stream of paths, split into shards for parallel work
    stream = sl.LazyStream.from_mapping({"path": source_paths}, shard_count=shard_count)
    return stream.transform(extract_columns, chunked=True, feed_column=["path"])


def publish(collection, repo_name):
    # Push the transformed collection and reopen it from the hub
    collection.push(repo_name, workers=4)
    logging.info("Published to %s", repo_name)
    return sl.open_collection(repo_name)


def main(argv):
    logging.basicConfig(level=logging.INFO)
    if argv:
        sources = [str(p) for p in Path(argv[0]).glob("*.csv")]
    else:
        sources = ["readings-a.csv", "readings-b.csv"]
    collection = build_collection(sources, shard_count=8)
    reopened = publish(collection, repo_name="acme-lab/sensor-readings")
    logging.info("Reopened collection with %d shards", reopened.shard_count)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

import logging
import sys
import traceback

import eventtrail as et


class Worker:
    def __init__(self, name):
        self.name = name

    def run(self):
        # Any failure is recorded with its full traceback instead of being lost
        try:
            self._perform_step()
        except Exception:
            et.record_failure(
                "worker_failed",
                worker=self.name,
                stack=traceback.format_exc(),
            )
            return False
        return True

    def _perform_step(self):
        raise RuntimeError("simulated failure")


def main(argv):
    logging.basicConfig(level=logging.DEBUG)
    et.start_trail(output=argv[0] if argv else "trail.log")
    ok = Worker("ingest").run()
    et.finish_trail()
    logging.info("Worker finished, success=%s", ok)
    return 0 if ok else 1


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

