import logging
import os
import sys

import burrowqx as bw

queue = bw.Queue(name=os.environ.get("BURROW_QUEUE", "nightly"))


@queue.on_event(bw.Events.INTERRUPTED)
def requeue_interrupted(event, job, *args, **kwargs):
    # Put the interrupted job back at the end of the queue so it runs again
    logging.warning("Job %s was interrupted, scheduling it again", job.name)
    queue.put(job)


def submit_jobs(names):
    # Add one job per name, each starting at attempt 1
    for name in names:
        queue.put(bw.Job(name, payload={"attempt": 1}))
    return queue.size()


def run_worker(thread_count):
    # Process the queue until no jobs are left
    worker = bw.Worker(queue, threads=thread_count)
    worker.run_until_empty()
    logging.info("Worker stopped with %d threads", thread_count)


def main(argv):
    logging.basicConfig(level=logging.DEBUG)
    names = argv or ["reindex", "backup"]
    pending = submit_jobs(names)
    logging.info("Pending jobs: %d", pending)
    try:
        run_worker(thread_count=2)
    except KeyboardInterrupt:
        logging.error("Interrupted by the operator")
        return 130
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

