import jobrack as jr


@jr.step(default=True)
def assemble_everything(ctx):
    # Default action: produce every artifact of the project
    print("assembling every package")


@jr.step
def assemble_archive(ctx):
    # Smaller action that only packs the release archive
    print("packing the release archive")


@jr.step
def render_docs(ctx):
    # Documentation is built from the same sources
    print("rendering documentation")


everything = jr.Bundle(all=assemble_everything, archive=assemble_archive)
docs = jr.Bundle(render_docs)


def main(argv):
    logging.basicConfig(level=logging.DEBUG)
    registry = jr.Registry()
    registry.add_bundle("build", everything)
    registry.add_bundle("docs", docs)
    target = os.environ.get("JOBRACK_TARGET", argv[0] if argv else "build.all")
    logging.info("Running %s", target)
    try:
        registry.run(target, context={"verbose": True})
    except jr.UnknownStep as exc:
        logging.error("Unknown step: %s", exc)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

