import argparse
import collections
import json
import sys

import cargoshape

Profile = collections.namedtuple("Profile", "nickname joined_on")


class ProfileBlueprint(cargoshape.Blueprint):
    nickname = cargoshape.Text()
    joined_on = cargoshape.Stamp()

    def legacy_factory(self, data):
        return Profile(**data)


class ProfileBlueprintV2(cargoshape.Blueprint):
    nickname = cargoshape.Text()
    joined_on = cargoshape.Stamp()

    @cargoshape.on_build
    def build_profile(self, data):
        return Profile(**data)


def main(argv=None):
    parser = argparse.ArgumentParser(description="Load profiles with cargoshape")
    parser.add_argument("input_file")
    parser.add_argument("--legacy", action="store_true")
    args = parser.parse_args(argv)
    blueprint = ProfileBlueprint() if args.legacy else ProfileBlueprintV2()
    try:
        profiles = blueprint.load(json.load(open(args.input_file, encoding="utf-8")))
    except cargoshape.ValidationFault as exc:
        print(f"invalid input: {exc.errors}", file=sys.stderr)
        return 1
    for profile in profiles:
        print(profile)
    return 0


if __name__ == "__main__":
    sys.exit(main())

