import argparse
import logging
import sys

import tokenbridge
from tokenbridge.models import AppRecord


class KeyChecker(tokenbridge.CheckerBase):
    """Accept only app keys that exist in the registry table."""

    def check_app_key(self, app_key, ctx):
        try:
            AppRecord.store.where(app_key=app_key).single()
            return True
        except tokenbridge.MissingRecord:
            return False


def run_checks(checker, keys):
    """Return a mapping of each key to its validation result."""
    results = {}
    for key in keys:
        results[key] = checker.check_app_key(key, ctx={})
    return results


def main(argv=None):
    parser = argparse.ArgumentParser(description="Validate app keys")
    parser.add_argument("keys", nargs="+")
    args = parser.parse_args(argv)
    checker = KeyChecker()
    results = run_checks(checker, args.keys)
    for key, ok in results.items():
        logging.info("%s -> %s", key, "valid" if ok else "rejected")
    return 0 if all(results.values()) else 1


if __name__ == "__main__":
    logging.basicConfig(format="%(message)s")
    sys.exit(main())

