import argparse
import logging
import sys

import proctally


def describe(proc):
    """Return one printable line for a process."""
    return f"{proc.ident} {proc.label()} {proc.state()}"


def list_processes(limit=None):
    """Collect printable lines, skipping processes that disappear mid-scan."""
    rows = []
    for proc in proctally.snapshot():
        try:
            rows.append(describe(proc))
        except (proctally.Vanished, proctally.Forbidden):
            # The process ended or we lack rights; skip it silently
            continue
        if limit and len(rows) >= limit:
            break
    return rows


def main(argv=None):
    parser = argparse.ArgumentParser(description="List processes")
    parser.add_argument("--limit", type=int, default=None)
    args = parser.parse_args(argv)
    for line in list_processes(args.limit):
        print(line)
    logging.info("done")
    return 0


if __name__ == "__main__":
    logging.basicConfig(format="%(message)s")
    sys.exit(main())

