import json
import logging
import os
import sys

import hangarq

logging.basicConfig(level=logging.INFO)
log = logging.getLogger("welcome")


def make_backlog():
    # Arma el backlog sobre un almacén en memoria, con la dirección tomada del entorno
    store = hangarq.MemoryStore(address=os.getenv("HANGAR_ADDRESS", "local"))
    return hangarq.Backlog(store=store, lane="mail")


def send_greeting(member_id):
    # Worker que entregaría el mensaje de bienvenida al socio
    log.info("saludo enviado a %s", member_id)


def schedule_greeting(backlog, member_id):
    # Agrega la tarea con una clave fija para que un segundo intento sea rechazado
    key = "greet-" + str(member_id)
    try:
        return backlog.push(send_greeting, member_id, key=key, dedupe=True)
    except hangarq.RepeatTicketError:
        log.warning("tarea ya registrada para %s", member_id)
        return None


def main():
    # Agenda dos veces el saludo del socio indicado y muestra si cada intento fue aceptado
    if len(sys.argv) < 2:
        raise SystemExit("uso: hangarq-welcome ID_SOCIO")
    backlog = make_backlog()
    first = schedule_greeting(backlog, sys.argv[1])
    second = schedule_greeting(backlog, sys.argv[1])
    print(json.dumps({"first": first is not None, "second": second is not None}))
    return 0


if __name__ == "__main__":
    sys.exit(main())

