class GreetingResponder(glowroute.Responder):
    # Answers GET calls on the root path with a fixed message
    def get(self):
        self.send("Greetings, traveller")


def build_router():
    # Map the root path to the responder class
    return glowroute.Router([("/", GreetingResponder)])


def start_server(port):
    # Create the server, start it and return the handle
    router = build_router()
    handle = glowroute.Server(router)
    handle.start(port=port)
    log.info("serving on port %s", port)
    return handle


