import json
import logging
import sys

import hashfold

log = logging.getLogger("cmp")


def normalize(raw):
    # Colapsa los espacios y pasa el texto a minúsculas antes de calcular la huella
    return " ".join(raw.split()).lower()


def build_digest(raw):
    # Calcula la huella difusa del contenido normalizado
    return hashfold.Digest(normalize(raw), width=64)


def compare_pairs(base_text, second, third):
    # Compara el texto base con otros dos y devuelve los puntajes de cercanía
    base = build_digest(base_text)
    return {
        "identico": base.closeness(build_digest(second)),
        "distinto": base.closeness(build_digest(third)),
    }


def main():
    # Textos de ejemplo: una copia del original y un párrafo sin relación
    original = "El río atraviesa la ciudad y llega al puerto principal."
    duplicate = original
    other = "Una receta sencilla de postre con frutas frescas y crema."
    scores = compare_pairs(original, duplicate, other)
    for label, value in scores.items():
        print(f"{label}: {value:.2f}")
    signature = hashfold.signature_of(normalize(original))
    print(json.dumps({"signature": signature}))
    log.info("comparación lista")
    return 0


if __name__ == "__main__":
    sys.exit(main())

