import json
import logging
import sys

import formshape

log = logging.getLogger("shape")


class PairShape(formshape.Shape):
    # Two whole-number slots; the left value must be strictly greater than the right one
    left = formshape.Whole(mandatory=True)
    right = formshape.Whole(mandatory=True)

    @formshape.check_pair(skip_on_slot_errors=False)
    def check_order(self, data):
        # Reject the pair when the left value is not larger than the right one
        if "left" in data and "right" in data:
            if data["left"] <= data["right"]:
                raise formshape.Problem("left must be larger than right")


def load_pair(shape, raw):
    # Validate the raw dictionary and return the clean data, or None on failure
    try:
        return shape.load(raw)
    except formshape.Problem as error:
        log.warning("invalid pair: %s", error)
        return None


def main():
    # Validate one pair given on the command line as two numbers
    shape = PairShape()
    left = int(sys.argv[1]) if len(sys.argv) > 1 else 2
    right = int(sys.argv[2]) if len(sys.argv) > 2 else 5
    clean = load_pair(shape, {"left": left, "right": right})
    print(json.dumps({"valid": clean is not None}))
    return 0 if clean is not None else 1


if __name__ == "__main__":
    sys.exit(main())

