import lexiterm

logger = logging.getLogger("lexi")

COMMAND_TREE = {
    "status": {
        "uptime": None,
        "memory": None,
        "ip": {"route_table": {"summary"}},
    },
    "exit": None,
}


def build_suggester(tree: dict) -> lexiterm.TreeSuggester:
    # Build the suggester from the nested command tree
    suggester = lexiterm.TreeSuggester.from_mapping(tree)
    logger.debug("suggester built with %d top-level commands", len(tree))
    return suggester


def read_command(suggester: lexiterm.TreeSuggester) -> str:
    # Ask for one line and let the user tab through the tree
    return lexiterm.read_line("> ", suggester=suggester)


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description="Command reader")
    parser.add_argument("--verbose", action="store_true")
    args = parser.parse_args(argv)
    logging.basicConfig(level=logging.DEBUG if args.verbose else logging.WARNING)
    suggester = build_suggester(COMMAND_TREE)
    try:
        text = read_command(suggester)
    except lexiterm.Interrupted:
        logger.info("input cancelled")
        return 130
    print(f"Received: {text}")
    return 0


if __name__ == "__main__":
    sys.exit(main())

