import kvfleetqx

logger = logging.getLogger("flota")

MAINTENANCE = kvfleetqx.MaintenanceWindow(active=True, extended_timeout=30)


def build_replica(address: str, share: float) -> kvfleetqx.Replica:
    # Réplica con su proporción de tráfico y opciones de enlace
    link_options = {"wire_version": 3, "read_timeout": 5, "maintenance": MAINTENANCE}
    return kvfleetqx.Replica(address=address, share=share, link_options=link_options)


def build_plan() -> kvfleetqx.FleetPlan:
    # La primaria recibe el doble de tráfico que la secundaria
    replicas = [
        build_replica("kv://db-primary:6379/0", share=1.0),
        build_replica("kv://db-secondary:6379/0", share=0.5),
    ]
    logger.info("plan armado con %d réplicas", len(replicas))
    return kvfleetqx.FleetPlan(replicas=replicas)


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description="Planificador de flota")
    parser.add_argument("--dry-run", action="store_true")
    args = parser.parse_args(argv)
    logging.basicConfig(level=logging.INFO)
    plan = build_plan()
    try:
        if args.dry_run:
            print(plan.describe())
        else:
            client = kvfleetqx.open(plan)
            client.ping()
    except kvfleetqx.FleetError as exc:
        logger.error("error de flota: %s", exc)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

